"""Generate the reviewable parameter catalog from installed block metadata."""

import argparse
import json
from pathlib import Path

from opencv_dataflow.blocks import builtin_registry


def render():
    lines = [
        "# Block parameter reference",
        "",
        "Generated by `python scripts/block_parameter_reference.py`. Defaults and enum choices",
        "come from the same metadata used by the inspector. Enums are dropdowns, booleans",
        "are checkboxes, and vectors/matrices use JSON fields. Image/data inputs are ports,",
        "not hidden parameters. Native output buffers, in-place pointers and backend internals",
        "are managed by the runtime. Some controls apply only to the selected method or codec.",
        "Image inputs also have an inspector pyramid-level dropdown (largest by default).",
        "See [payloads, channels and pyramids](payloads-pyramids.md) for coordinate provenance.",
        "",
    ]
    for kind, cls in sorted(builtin_registry().types.items()):
        lines.extend(
            [
                f"## {cls.title} (`{kind}`)",
                "",
                f"{cls.block_type or cls.category} / {cls.subtype}",
                "",
            ]
        )
        if cls.inputs:
            lines.append(
                "Inputs: "
                + ", ".join(
                    f"`{p.name}` ({p.kind}{', optional' if not p.required else ''})"
                    for p in cls.inputs
                )
                + "."
            )
            lines.append("")
        if hasattr(cls, "region_outputs"):
            lines.extend(
                [
                    "Selection writes: "
                    + ", ".join(f"`{p}`" for p in cls.region_outputs)
                    + f"; outside policy: `{cls.region_background}`"
                    + " (preserve requires matching channels).",
                    "Neighborhood operations retain full-image context. See [regions](regions.md).",
                    "",
                ]
            )
        if not cls.defaults:
            lines.extend(["No configurable algorithm parameters.", ""])
            continue
        lines.extend(["| Parameter | Default | Enum choices / help |", "| --- | --- | --- |"])
        for name, value in cls.defaults.items():
            choices = ", ".join(f"`{x}`" for x in cls.parameter_choices.get(name, ()))
            help_text = cls.parameter_help.get(name, "").replace("|", "\\|")
            description = " ".join(part for part in (choices, help_text) if part)
            lines.append(f"| `{name}` | `{json.dumps(value)}` | {description} |")
        lines.append("")
    return "\n".join(lines)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    path = Path(__file__).resolve().parents[1] / "docs/block-parameters.md"
    content = render()
    if args.check:
        if not path.exists() or path.read_text(encoding="utf-8") != content:
            raise SystemExit("Block parameter reference is out of date")
        print("Block parameter reference is current")
    else:
        path.write_text(content, encoding="utf-8")
